def apply(inputs, premises):
    question = inputs["current_question"]
    permitted_classes = []
    if "permitted_representative_classes" in premises:
        permitted_classes = premises["permitted_representative_classes"]
    class_match = False
    for recipient_class in permitted_classes:
        if recipient_class in question:
            class_match = True
    if "professional advisors" in question:
        if "legal advisors" in permitted_classes or "financial advisors" in permitted_classes or "accountants" in permitted_classes:
            class_match = True
    confidentiality_condition = False
    if "representatives_must_be_confidentiality_bound" in premises:
        confidentiality_condition = premises["representatives_must_be_confidentiality_bound"]
    need_condition = False
    if "representatives_must_have_bona_fide_need_to_know" in premises:
        need_condition = premises["representatives_must_have_bona_fide_need_to_know"]
    purpose_condition = False
    if "disclosure_limited_to_business_purpose" in premises:
        purpose_condition = premises["disclosure_limited_to_business_purpose"]
    exception_applies = class_match and confidentiality_condition and need_condition and purpose_condition
    return {"exception_applies": exception_applies}

def apply(inputs, premises):
    question = inputs["current_question"]
    is_disclosure_permission_query = "Receiving Party" in question and "may share some Confidential Information" in question
    general_rule = False
    if "general_third_party_nondisclosure_rule" in premises:
        general_rule = premises["general_third_party_nondisclosure_rule"]
    subject_to_representative_exception = False
    if "prohibition_expressly_subject_to_paragraph4" in premises:
        subject_to_representative_exception = premises["prohibition_expressly_subject_to_paragraph4"]
    if not is_disclosure_permission_query or not general_rule:
        answer = "NotMentioned"
    elif inputs["representative_exception_applies"]:
        answer = "Entailment"
    elif "some third-parties" in question:
        answer = "Contradiction"
    elif subject_to_representative_exception:
        answer = "Contradiction"
    else:
        answer = "NotMentioned"
    return {"answer": answer}
